#!/usr/bin/env python3
"""Generate/check the local native-PDF worker. Development only; no office Python."""
import argparse
import hashlib
import json
import re
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parent
OUTPUT = ROOT / 'parser-worker-source.js'
INFO = ROOT / 'build-info.json'
ADAPTER = ROOT.parent.parent / 'assets/pdf.js'
SOURCES = ('pdf.worker.js', 'pdf.js', 'parser-core.js', 'build-worker-source.py')
PREFIX = """'use strict';
self.fetch=async function(){throw Error('PDF worker network access is disabled.');};
self.importScripts=function(){throw Error('PDF worker script imports are disabled.');};
// Keep PDF.js's internal fake-worker port separate from the parent message port.
self.window=self;
"""
ENTRY = """
self.onmessage=async function(event){
 try {
  if(!event.data||!(event.data.bytes instanceof ArrayBuffer))throw Error('Invalid native PDF worker request.');
  const result=await PBGCRag.extractPdfBytes(new Uint8Array(event.data.bytes),event.data.options||{});
  self.postMessage({ok:true,result});
 } catch(error) {
  self.postMessage({ok:false,error:String(error.message||error)});
 }
};
"""


def text(name):
    # Normalized source hashes make --check stable on Windows CRLF checkouts.
    return (ROOT / name).read_text(encoding='utf-8')


def digest(value):
    return hashlib.sha256(value.encode('utf-8')).hexdigest()


def generated():
    core = text('parser-core.js')
    required = ('isEvalSupported:false', 'useWorkerFetch:false', 'useWasm:false',
                'useSystemFonts:false', 'disableFontFace:true', 'enableXfa:false',
                'BinaryDataFactory:NoExternalData')
    if any(flag not in core for flag in required):
        raise ValueError('Native PDF isolation flags changed; review the parser before rebuilding.')
    source = PREFIX + text('pdf.worker.js') + '\ndelete self.window;\n' + text('pdf.js') + '\n' + core + ENTRY
    manifest = {'schemaVersion': 1, 'kind': 'pdf-native-parser-worker', 'pdfjs': '6.4.299',
                'sourceEncoding': 'UTF-8 with normalized LF',
                'sources': {name: digest(text(name)) for name in SOURCES},
                'worker': {'sha256': digest(source), 'bytes': len(source.encode('utf-8'))}}
    output = ('/* Generated by vendor/pdfjs/build-worker-source.py; PDF.js Apache-2.0. */\n'
              '(function(root){\'use strict\';root.PBGCRag=root.PBGCRag||{};root.PBGCRag.pdfWorkerSource='
              + json.dumps(source, separators=(',', ':'))
              + ';root.PBGCRag.pdfWorkerManifest=Object.freeze('
              + json.dumps(manifest, separators=(',', ':')) + ');})(globalThis);\n'
              + '/* Build provenance ' + json.dumps(manifest, separators=(',', ':')) + ' */\n')
    artifacts = {'parser-core.js': {'sha256': digest(core)},
                 'build-worker-source.py': {'sha256': digest(text('build-worker-source.py'))},
                 'parser-worker-source.js': {'sha256': digest(output)}}
    adapter = ADAPTER.read_text(encoding='utf-8')
    pinned, count = re.subn(r"const PDF_NATIVE_WORKER_SHA256='[a-f0-9]{64}';",
                          "const PDF_NATIVE_WORKER_SHA256='" + digest(source) + "';", adapter)
    if count != 1:
        raise ValueError('Native PDF adapter must contain exactly one worker integrity pin.')
    return output, artifacts, adapter, pinned


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    try:
        output, artifacts, adapter, pinned = generated()
        info = json.loads(INFO.read_text(encoding='utf-8'))
        if args.check:
            if (not OUTPUT.exists() or OUTPUT.read_text(encoding='utf-8') != output
                    or info.get('workerArtifacts') != artifacts or adapter != pinned):
                print('Native PDF worker/provenance is stale; run python vendor/pdfjs/build-worker-source.py.', file=sys.stderr)
                return 1
            print('Native PDF worker source and provenance are current.')
            return 0
        OUTPUT.write_text(output, encoding='utf-8', newline='\n')
        ADAPTER.write_text(pinned, encoding='utf-8', newline='\n')
        info['workerArtifacts'] = artifacts
        INFO.write_text(json.dumps(info, indent=2) + '\n', encoding='utf-8', newline='\n')
        print('Generated native PDF worker with bounded-request and SHA-256 provenance.')
        return 0
    except (OSError, ValueError) as error:
        print(str(error), file=sys.stderr)
        return 1


if __name__ == '__main__':
    raise SystemExit(main())
